2. Create integration test file (e.g., `packages/cli/test/integration/enigma-command.test.ts`):
```typescript
import { execSync } from 'child_process';
import * as fs from 'fs-extra';
import * as path from 'path';

describe('enigma command integration', () => {
  const fixtureDir = path.resolve(__dirname, '../fixtures/sample-project');
  const buildDir = path.join(fixtureDir, 'dist');
  const cliPath = path.resolve(__dirname, '../../bin/enigma.js');

  beforeEach(async () => {
    // Setup test fixture
    await fs.ensureDir(buildDir);
    await fs.copy(
      path.join(fixtureDir, 'source'),
      buildDir
    );
  });

  afterEach(async () => {
    // Cleanup
    await fs.remove(buildDir);
  });

  test('basic optimization works', async () => {
    // Run the command
    const result = execSync(
      `node ${cliPath} --build-dir ${buildDir}`,
      { encoding: 'utf8' }
    );

    // Verify output
    expect(result).toContain('Optimization complete');

    // Verify files were modified
    const outputCss = await fs.readFile(
      path.join(buildDir, 'enigma.css'),
      'utf8'
    );
    expect(outputCss).toContain('@apply');

    // Verify HTML was rewritten
    const html = await fs.readFile(
      path.join(buildDir, 'index.html'),
      'utf8'
    );
    expect(html).not.toContain('top-0 z-50 w-full');
    // Instead should contain a short identifier
  });

  test('dry run mode does not modify files', async () => {
    // Get file contents before
    const htmlBefore = await fs.readFile(
      path.join(buildDir, 'index.html'),
      'utf8'
    );

    // Run in dry run mode
    const result = execSync(
      `node ${cliPath} --build-dir ${buildDir} --dry-run`,
      { encoding: 'utf8' }
    );

    // Verify output indicates dry run
    expect(result).toContain('DRY RUN MODE');

    // Verify files were not modified
    const htmlAfter = await fs.readFile(
      path.join(buildDir, 'index.html'),
      'utf8'
    );
    expect(htmlAfter).toBe(htmlBefore);

    // Verify CSS was not created
    const cssExists = await fs.pathExists(
      path.join(buildDir, 'enigma.css')
    );
    expect(cssExists).toBe(false);
  });

  // Add more tests for scramble integration, error scenarios, etc.
});
```

